public abstract class Empleado {
    protected String nombre;
    protected double salarioBase;

    public Empleado(String nombre, double salarioBase) {
        this.nombre = nombre;
        this.salarioBase = salarioBase;
    }

    // Metodo abstracto: cada subclase DEBE implementarlo
    public abstract double calcularSalario();
    public abstract String getRol();

    // Metodo concreto: logica compartida
    public String getInfo() {
        return nombre + " (" + getRol() + "): "
             + String.format("%.2f", calcularSalario()) + " EUR";
    }

    public boolean ganaMasQue(Empleado otro) {
        return this.calcularSalario() > otro.calcularSalario();
    }
}

public class Profesor extends Empleado {
    private String especialidad;

    public Profesor(String nombre, double salario, String especialidad) {
        super(nombre, salario);
        this.especialidad = especialidad;
    }

    @Override
    public double calcularSalario() {
        return salarioBase + 500; // complemento por especialidad
    }

    @Override
    public String getRol() { return "Profesor de " + especialidad; }
}

public class Administrativo extends Empleado {
    private String categoria;

    public Administrativo(String nombre, double salario, String categoria) {
        super(nombre, salario);
        this.categoria = categoria;
    }

    @Override
    public double calcularSalario() {
        return salarioBase;
    }

    @Override
    public String getRol() { return "Administrativo (" + categoria + ")"; }
}

public class GestionEmpleados {
    public static void main(String[] args) {
        // Polimorfismo: array de tipo Empleado contiene diferentes tipos
        Empleado[] equipo = {
            new Profesor("Garcia", 2200, "Java"),
            new Profesor("Martinez", 2400, "Bases de Datos"),
            new Administrativo("Lopez", 1600, "Senior"),
            new Administrativo("Fernandez", 1400, "Junior")
        };

        // Recorrer y tratar todos como Empleado
        // Java sabe cual metodo ejecutar en tiempo de ejecucion
        for (Empleado e : equipo) {
            // getInfo() usa calcularSalario() y getRol() -> dynamic dispatch
            System.out.println(e.getInfo());
        }

        // Encontrar quien gana mas
        Empleado mejor = equipo[0];
        for (Empleado e : equipo) {
            if (e.ganaMasQue(mejor)) {
                mejor = e;
            }
        }
        System.out.println("\nMejor pagado: " + mejor.getNombre()
             + " (" + String.format("%.2f", mejor.calcularSalario()) + " EUR)");
    }
}

public class GestorNomina {
    // Metodo que acepta cualquier tipo de Empleado
    public static void mostrarNomina(Empleado empleado) {
        System.out.println("Nomina: " + empleado.getNombre()
             + " | Rol: " + empleado.getRol()
             + " | Salario: " + String.format("%.2f", empleado.calcularSalario()));
    }

    // Metodo que procesa un array de cualquier tipo de Empleado
    public static void listarPorRol(Empleado[] empleados, String rolBuscado) {
        System.out.println("\n=== Empleados tipo: " + rolBuscado + " ===");
        for (Empleado e : empleados) {
            if (e.getRol().contains(rolBuscado)) {
                System.out.println("  " + e.getNombre() + " - " + e.getInfo());
            }
        }
    }

    // Metodo que calcula gasto total (polimorfismo puro)
    public static double calcularGastoTotal(Empleado[] empleados) {
        double total = 0;
        for (Empleado e : empleados) {
            total += e.calcularSalario(); // Cada tipo calcula diferente
        }
        return total;
    }

    public static void main(String[] args) {
        Empleado[] equipo = {
            new Profesor("Garcia", 2200, "Java"),
            new Profesor("Martinez", 2400, "BD"),
            new Administrativo("Lopez", 1600, "Senior")
        };

        for (Empleado e : equipo) {
            mostrarNomina(e); // Polimorfismo: cada llamada usa la version correcta
        }

        System.out.println("\nGasto total: "
             + String.format("%.2f", calcularGastoTotal(equipo)) + " EUR");
    }
}

A veces necesitas saber el tipo real de un objeto en runtime. Para eso usas `instanceof`:

```java
if (empleado instanceof Profesor) {
    // Es un Profesor
    Profesor p = (Profesor) empleado; // Casting manual
    System.out.println("Especialidad: " + p.getEspecialidad());
}
```

**`instanceof`** comprueba si un objeto es de un tipo determinado (o de una subclase de ese tipo).

**Casting** se usa para acceder a campos/métodos que solo existen en la subclase. Pero ten cuidado: si haces casting a un tipo que no es, obtienes un `ClassCastException`.

**Pattern matching** (desde Java 16): forma abreviada de comprobar y convertir en una sola línea:

```java
if (empleado instanceof Profesor p) {
    // 'p' ya está convertido, no necesitas casting manual
    System.out.println("Especialidad: " + p.getEspecialidad());
}
```

public class AnalizadorEquipo {
    public static void analizar(Empleado[] empleados) {
        for (Empleado e : empleados) {
            System.out.print(e.getNombre() + ": ");

            // Pattern matching (Java 16+)
            if (e instanceof Profesor p) {
                System.out.println("Profesor de " + p.getEspecialidad()
                     + " | Salario: " + String.format("%.2f", p.calcularSalario()));
            } else if (e instanceof Administrativo a) {
                System.out.println("Administrativo " + a.getCategoria()
                     + " | Salario: " + String.format("%.2f", a.calcularSalario()));
            } else {
                System.out.println("Empleado desconocido");
            }
        }
    }

    public static void main(String[] args) {
        Empleado[] equipo = {
            new Profesor("Garcia", 2200, "Java"),
            new Administrativo("Lopez", 1600, "Senior"),
            new Profesor("Martinez", 2400, "BD")
        };
        analizar(equipo);
    }
}

Además de arrays, puedes usar `ArrayList` para colecciones polimórficas. La ventaja es que puedes añadir y eliminar elementos dinámicamente:

```java
import java.util.ArrayList;
import java.util.List;

List<Empleado> equipo = new ArrayList<>();
equipo.add(new Profesor("Garcia", 2200, "Java"));
equipo.add(new Administrativo("Lopez", 1600, "Senior"));

// Polimorfismo: recorrer y usar
for (Empleado e : equipo) {
    System.out.println(e.getInfo());
}
```

`ArrayList<Empleado>` puede contener cualquier subclase de `Empleado`. El polimorfismo funciona igual que con arrays, pero con más flexibilidad.

// Java 21: switch expressions con pattern matching
public class ClasificadorEmpleados {

    // Forma clasica (pre-Java 21)
    public static String clasificar(Empleado e) {
        if (e instanceof Profesor p) {
            return "Profesor: " + p.getEspecialidad();
        } else if (e instanceof Administrativo a) {
            return "Admin: " + a.getCategoria();
        } else {
            return "Otro empleado";
        }
    }

    // Forma moderna: switch expression (Java 21+)
    public static String clasificarModern(Empleado e) {
        return switch (e) {
            case Profesor p   -> "Profesor: " + p.getEspecialidad();
            case Administrativo a -> "Admin: " + a.getCategoria();
            default            -> "Otro empleado";
        };
    }

    // Switch con guardas (Java 21+)
    public static String getNivel(Empleado e) {
        return switch (e) {
            case Profesor p when p.calcularSalario() > 3000
                -> "Profesor Senior";
            case Profesor p
                -> "Profesor Junior";
            case Administrativo a when a.getCategoria().equals("Senior")
                -> "Admin Senior";
            case Administrativo a
                -> "Admin Junior";
            default -> "Sin clasificar";
        };
    }

    public static void main(String[] args) {
        Empleado[] equipo = {
            new Profesor("Garcia", 3200, "Java"),
            new Profesor("Martinez", 2000, "BD"),
            new Administrativo("Lopez", 1600, "Senior"),
            new Administrativo("Fernandez", 1400, "Junior")
        };

        for (Empleado e : equipo) {
            System.out.println(e.getNombre() + " -> " + clasificarModern(e));
            System.out.println("  Nivel: " + getNivel(e));
        }
    }
}

