public abstract class Figura {
    protected String nombre;
    public Figura(String n) { this.nombre = n; }
    public abstract double getArea();
    @Override public String toString() {
        return nombre + ": " + String.format("%.2f", getArea());
    }
}

public class Circulo extends Figura {
    private double r;
    public Circulo(double r) { super("Circulo"); this.r = r; }
    @Override public double getArea() { return Math.PI * r * r; }
}

public class Rectangulo extends Figura {
    private double b, h;
    public Rectangulo(double b, double h) { super("Rectangulo"); this.b = b; this.h = h; }
    @Override public double getArea() { return b * h; }
}

public class Triangulo extends Figura {
    private double b, h;
    public Triangulo(double b, double h) { super("Triangulo"); this.b = b; this.h = h; }
    @Override public double getArea() { return (b * h) / 2; }
}

public class Demo {
    public static void main(String[] args) {
        Figura[] figuras = {
            new Circulo(5),
            new Rectangulo(10, 5),
            new Triangulo(8, 6)
        };
        for (Figura f : figuras) {
            System.out.println(f); // Polimorfismo
        }
    }
}

