public abstract class SistemaCalificacion {
    protected String nombre;
    public SistemaCalificacion(String n) { this.nombre = n; }
    public abstract String calificar(double nota);
    @Override public String toString() { return nombre; }
}

public class SistemaTradicional extends SistemaCalificacion {
    public SistemaTradicional() { super("Tradicional (0-10)"); }
    @Override public String calificar(double nota) {
        if (nota >= 9) return "Sobresaliente";
        if (nota >= 7) return "Notable";
        if (nota >= 5) return "Aprobado";
        return "Suspenso";
    }
}

public class SistemaABC extends SistemaCalificacion {
    public SistemaABC() { super("ABC"); }
    @Override public String calificar(double nota) {
        if (nota >= 9) return "A";
        if (nota >= 7) return "B";
        if (nota >= 5) return "C";
        if (nota >= 3) return "D";
        return "F";
    }
}

public class SistemaMorses extends SistemaCalificacion {
    public SistemaMorses() { super("Morses"); }
    @Override public String calificar(double nota) {
        return nota >= 5 ? "...- (Aprobado)" : "-. (Suspenso)";
    }
}

public class Demo {
    public static String nombreSistema(SistemaCalificacion s) {
        return switch (s) {
            case SistemaTradicional t -> "Tradicional";
            case SistemaABC a         -> "ABC";
            case SistemaMorses m      -> "Morses";
            default                   -> "Desconocido";
        };
    }

    public static void main(String[] args) {
        SistemaCalificacion[] sistemas = {
            new SistemaTradicional(), new SistemaABC(), new SistemaMorses()
        };
        double[] notas = {8.5, 4.0, 9.2, 6.0};

        for (SistemaCalificacion s : sistemas) {
            System.out.println("\n--- " + nombreSistema(s) + " ---");
            for (double n : notas) {
                System.out.printf("Nota %.1f -> %s%n", n, s.calificar(n));
            }
        }
    }
}

