public interface Pagable {
    void pagar();
    double getPrecio();
    boolean isPagado();
}

public interface Describable {
    String getDescripcion();
}

public interface Exportable {
    String exportarJSON();
}

public class CursoOnline implements Pagable, Describable, Exportable {
    private String nombre;
    private double precio;
    private boolean pagado = false;

    public CursoOnline(String nombre, double precio) {
        this.nombre = nombre;
        this.precio = precio;
    }

    @Override public void pagar() { pagado = true; }
    @Override public double getPrecio() { return precio; }
