        super(n, s);
        this.especialidad = esp;
    }

    @Override public double calcularSalario() { return salarioBase + 500; }
    @Override public String getRol() { return "Profesor de " + especialidad; }

    // Exportable
    @Override public String exportarJSON() {
        return "{\"nombre\":\"" + nombre + "\",\"salario\":" + calcularSalario() + "}";
