        n.enviarNotificacion(asunto, msg);
    }

    // Polimorfismo: buscar en cualquier Buscable
    public static void buscar(Buscable[] items, String termino) {
        System.out.println("Buscando: \"" + termino + "\"");
        for (Buscable b : items) {
            if (b.contiene(termino)) {
                System.out.println("  Encontrado: " + b);
            }
        }
    }

    public static void main(String[] args) {
        // Crear direcciones (composicion)
        Direccion dirMadrid = new Direccion("Calle Mayor", "Madrid", "28001");
        Direccion dirBuenosAires = new Direccion("Av. Libertad", "Buenos Aires", "C1000");
        Direccion dirTokio = new Direccion("Shibuya", "Tokio", "150-0001");

        // Crear alumnos (herencia + composicion + interfaces)
        Alumno[] alumnos = {
            new Alumno("Ana Garcia", "ana@email.com", 20, 8.5, dirMadrid, "MAT-001"),
            new Becario("Carlos Lopez", "carlos@email.com", 22, 7.0,
                       dirMadrid, "MAT-002", "BEC-2026-001", 25.0),
            new Internacional("Yuki Tanaka", "yuki@email.com", 21, 9.2,
                             dirTokio, "MAT-003", "Japon", "Japones"),
            new Alumno("Maria Rodriguez", "maria@email.com", 19, 6.8,
                      dirBuenosAires, "MAT-004")
        };

        // === 1. POLIMORFISMO: mostrar info de todos ===
        System.out.println("=== TODOS LOS ALUMNOS ===");
        for (Alumno a : alumnos) {
            System.out.println(a); // toString() polimorfico
        }

        // === 2. INTERFACES: exportar a JSON ===
        System.out.println("\n=== EXPORTAR A JSON ===");
        for (Alumno a : alumnos) {
            exportar(a); // Polimorfismo con Exportable
        }

        // === 3. COMPARABLE: ordenar por nota ===
        System.out.println("\n=== ORDENADOS POR NOTA ===");
        Arrays.sort(alumnos); // compareTo() de Comparable
        for (Alumno a : alumnos) {
            System.out.println("  " + a.getNombre() + " - " + a.getNotaMedia());
        }

        // === 4. COMPARATOR: ordenar por nombre ===
        System.out.println("\n=== ORDENADOS POR NOMBRE ===");
        Comparator<Alumno> porNombre = Comparator.comparing(Persona::getNombre);
        Arrays.sort(alumnos, porNombre);
        for (Alumno a : alumnos) {
            System.out.println("  " + a.getNombre());
        }

        // === 5. NOTIFICABLE: enviar notificacion ===
        System.out.println("\n=== ENVIAR NOTIFICACION ===
  Asunto: Nota del examen publicada");
        for (Alumno a : alumnos) {
            notificar(a, "Nota del examen",
                     "Su nota ha sido publicada en el campus.");
        }

        // === 6. BUSCABLE: buscar por termino ===
        System.out.println();
        buscar(alumnos, "ana");
        System.out.println();
        buscar(alumnos, "MAT-003");

        // === 7. INSTANCEOF: detectar tipos ===
        System.out.println("\n=== DETECCION DE TIPOS ===");
        for (Alumno a : alumnos) {
            if (a instanceof Becario b) {
                System.out.println(b.getNombre() + " es Becario con"
                     + " " + b.getPorcentajeDescuento() + "% descuento");
            } else if (a instanceof Internacional i) {
                System.out.println(i.getNombre() + " es de " + i.getPaisOrigen());
            } else {
                System.out.println(a.getNombre() + " es Alumno regular");
            }
        }

        // === 8. COMPOSICION: acceder a historial ===
        System.out.println("\n=== HISTORIAL ACADEMICO ===");
        alumnos[0].addNota("Java", 8.5);
        alumnos[0].addNota("Bases de Datos", 7.0);
        alumnos[0].addNota("Redes", 9.0);
        System.out.println(alumnos[0].getNombre() + ": media="
             + String.format("%.1f", alumnos[0].getHistorial().getMedia())
             + ", mejor materia: " + alumnos[0].getHistorial().getMejorMateria());
    }
}

