public interface Calificable {
    String calificar(double nota);
}

public interface Exportable {
    String exportarJSON();
}

public class Alumno implements Calificable, Exportable {
    protected String nombre;
    protected double notaMedia;

    public Alumno(String nombre, double notaMedia) {
        this.nombre = nombre;
        this.notaMedia = notaMedia;
    }

    public String getNombre() { return nombre; }
    public double getNotaMedia() { return notaMedia; }

    @Override
    public String calificar(double nota) {
        if (nota >= 9) return "Sobresaliente";
        if (nota >= 7) return "Notable";
        if (nota >= 5) return "Aprobado";
        return "Suspenso";
    }

    @Override
    public String exportarJSON() {
        return "{\"nombre\":\"" + nombre
             + "\",\"calificacion\":\"" + calificar(notaMedia) + "\"}";
    }

    @Override
    public String toString() {
        return nombre + " | " + String.format("%.1f", notaMedia)
             + " | " + calificar(notaMedia);
    }
}

public class Becario extends Alumno {
    public Becario(String nombre, double nota) { super(nombre, nota); }

    @Override
    public String calificar(double nota) {
        return super.calificar(nota) + " (Becado)";
    }
}

public class Internacional extends Alumno {
    private String pais;
    public Internacional(String nombre, double nota, String pais) {
        super(nombre, nota); this.pais = pais;
    }

    @Override
    public String calificar(double nota) {
        if (nota >= 8) return "A (Excelente)";
        if (nota >= 6) return "B (Good)";
        if (nota >= 4) return "C (Pass)";
        return "F (Fail)";
    }
}

