import java.util.ArrayList;
import java.util.List;

public class HistorialAcademico {
    private List<String> materias = new ArrayList<>();
    private List<Double> notas = new ArrayList<>();
    public void add(String m, double n) { materias.add(m); notas.add(n); }
    public double getMedia() {
        return notas.stream().mapToDouble(Double::doubleValue).average().orElse(0);
    }
    public String getMejor() {
        if (notas.isEmpty()) return "-";
        int idx = 0;
        for (int i = 1; i < notas.size(); i++)
            if (notas.get(i) > notas.get(idx)) idx = i;
        return materias.get(idx);
    }
}

public abstract class Persona implements Comparable<Persona> {
    protected String nombre, email;
    public Persona(String n, String e) { this.nombre = n; this.email = e; }
    public String getNombre() { return nombre; }
    @Override public int compareTo(Persona o) { return nombre.compareTo(o.nombre); }
}

public class Alumno extends Persona implements Exportable, Notificable {
    protected double notaMedia;
    protected Direccion direccion;
    protected HistorialAcademico historial = new HistorialAcademico();

    public Alumno(String n, String e, double nota, Direccion d) {
        super(n, e); this.notaMedia = nota; this.direccion = d;
    }

    public double getNotaMedia() { return notaMedia; }
    public HistorialAcademico getHistorial() { return historial; }
    public void addNota(String m, double n) { historial.add(m, n); }

    @Override public int compareTo(Persona o) {
        if (o instanceof Alumno a) return Double.compare(a.notaMedia, this.notaMedia);
        return super.compareTo(o);
    }

    @Override public String exportarJSON() {
        return "{\"nombre\":\"" + nombre + "\",\"email\":\"" + email
             + "\",\"notaMedia\":" + notaMedia + "}";
    }
    @Override public String exportarCSV() { return nombre + ";" + email + ";" + notaMedia; }
    @Override public void enviarNotificacion(String a, String m) {
        System.out.println("[EMAIL " + email + "] " + a + ": " + m);
    }
    @Override public String getCanalNotificacion() { return "EMAIL"; }
    @Override public String toString() { return nombre + " - " + String.format("%.1f", notaMedia); }
}

public class Becario extends Alumno {
    private String numBeca;
    public Becario(String n, String e, double nota, Direccion d, String beca) {
        super(n, e, nota, d); this.numBeca = beca;
    }
    @Override public String exportarJSON() {
        return super.exportarJSON().replace("}", ",\"beca\":\"" + numBeca + "\"}");
    }
    @Override public void enviarNotificacion(String a, String m) {
        super.enviarNotificacion(a, m);
        System.out.println("[SMS becado] " + a + ": " + m);
    }
    @Override public String getCanalNotificacion() { return "EMAIL + SMS"; }
    @Override public String toString() { return super.toString() + " [Beca: " + numBeca + "]"; }
}

public class Internacional extends Alumno {
    private String pais;
    public Internacional(String n, String e, double nota, Direccion d, String p) {
        super(n, e, nota, d); this.pais = p;
    }
    @Override public String exportarJSON() {
        return super.exportarJSON().replace("}", ",\"pais\":\"" + pais + "\"}");
    }
    @Override public String getCanalNotificacion() { return "EMAIL (" + pais + ")"; }
    @Override public String toString() { return super.toString() + " [" + pais + "]"; }
}

